      while code >= 256 {
        stackp.append( UInt8(htab[Int(code)]) )
        code = Int(codetab[Int(code)])
      }
      finchar = htab[Int(code)]
      stackp.append( UInt8(finchar) )


      /* And put them out in forward order.  */
      middle(&bp)
    }
    state = .S_EOF
    return bp // (num - count);
  }

  func start() throws(POSIXErrno) -> UInt8? {
    /* Check the magic number */
    guard let header = try? fp.readUpToCount(3),
          Array(header.prefix(2)) == magic_header else {
      errno = EFTYPE;
      return nil
    }
    maxbits = UInt(header[2])  /* Set -b from file. */
    block_compress = 0 != (maxbits & BLOCK_MASK)
    maxbits &= BIT_MASK
    maxmaxcode = 1 << maxbits;
    if maxbits > BITS || maxbits < 12 {
      throw POSIXErrno(EFTYPE)
    }
    /* As above, initialize the first 256 entries in the table. */
    n_bits = INIT_BITS
    maxcode = MAXCODE(n_bits)
    for code in UInt8(0)..<UInt8(255) {
      codetab[Int(code)] = 0
      htab[Int(code)] = Int(code)
    }
    free_ent = block_compress ? FIRST : 256;

    guard let oldcode = getcode() else {
      return nil  // EOF already
    }
    finchar = oldcode


    /* First code must be 8 bits = char. */
    return UInt8(finchar)
  }

  func middle(_ bp : inout [UInt8]) {
    while !stackp.isEmpty {
      bp.append( stackp.removeLast() )
    }

    /* Generate the new entry. */
    code = free_ent
    if code < maxmaxcode && oldcode != -1 {
      codetab[code] = UInt16(oldcode)
      htab[code] = finchar
      free_ent = code + 1
    }

    /* Remember previous code. */
    oldcode = incode;
  }

  /*-
   * Read one code from the standard input.  If EOF, return -1.
   * Inputs:
   * 	stdin
   * Outputs:
   * 	code or -1 is returned.
   */
  func getcode() -> Int? {
//    code_int gcode;
//    int r_off, bits;
//    char_type *bp;

    if clear_flg || roffset >= size || free_ent > maxcode {
      /*
       * If the next entry will be too big for the current gcode
       * size, then we must increase the size.  This implies reading
       * a new buffer full, too.
       */
      if free_ent > maxcode {
        n_bits += 1
        if n_bits == maxbits {	/* Won't get any bigger now. */
          maxcode = maxmaxcode
        }
        else {
          maxcode = MAXCODE(n_bits)
        }
      }
      if clear_flg {
        n_bits = INIT_BITS
        maxcode = MAXCODE(n_bits)
        clear_flg = false
      }
      let bp = try? fp.readUpToCount(Int(n_bits))
      guard let bp,
            buf.count > 0 else {	/* End of file. */
        return nil
      }
      gbuf = bp
      roffset = 0;
      /* Round size down to integral number of codes. */
      size = (size << 3) - (Int(n_bits) - 1)
    }
    var r_off = roffset
    var bits = n_bits

    /* Get to the first byte. */
    var bpo = r_off >> 3
    r_off &= 7

    /* Get first part (low order bits). */
    var gcode : UInt = UInt(gbuf[Int(bpo)]) >> r_off
    bpo += 1
    bits -= 8 - r_off
    r_off = 8 - r_off  	/* Now, roffset into gcode word. */

    /* Get any 8 bit parts in the middle (<=1 for up to 16 bits). */
    if bits >= 8 {
      gcode |= UInt(gbuf[Int(bpo)]) << r_off
      bpo += 1
      r_off += 8
      bits -= 8
    }

    /* High order bits. */
    gcode |= UInt(gbuf[Int(bpo)] & rmask[Int(bits)]) << r_off
    roffset += n_bits
    return Int(gcode)
  }

    /// Table clear for block compress.
  func cl_block() -> Bool {
    var checkpoint = in_count + CHECK_GAP
    var rat : UInt = 0

    if (in_count > 0x007fffff) {	/* Shift will overflow. */
      rat = bytes_out >> 8
      if rat == 0 {		/* Don't divide by zero. */
        rat = 0x7fffffff;
      }
      else {
        rat = in_count / rat
      }
    } else {
      rat = (in_count << 8) / bytes_out	/* 8 fractional bits. */
    }
    if rat > ratio {
      ratio = rat
    }
    else {
      ratio = 0
      cl_hash(hsize)
      free_ent = FIRST
      clear_flg = true
      if output(CLEAR) == -1 {
        return true
      }
    }
    return false
  }

  /// Reset code table.
  func cl_hash(_ cl_hsize : Int) {
    for i in 0..<htab.count { htab[i] = -1 }
  }

  init?(_ fname : String, _ xmode : String, _ bits : UInt? = nil) {

    switch xmode {
      case "r": mode = .readOnly
      case "w": mode = .writeOnly
      default:
        errno = EINVAL
        return nil
    }

    maxbits = bits ?? BITS	/* User settable max # bits/code. */
    if maxbits > BITS {
      errno = EINVAL
      return nil
    }

    maxmaxcode = 1 << maxbits	/* Should NEVER generate this code. */
    hsize = HSIZE 			/* For dynamic table sizing. */
    free_ent = 0			/* First unused entry. */
    block_compress = 0 != BLOCK_MASK
    clear_flg = false
    ratio = 0
    checkpoint = CHECK_GAP
    in_count = 1			/* Length of input. */
    out_count = 0			/* # of codes output (for debugging). */
    state = .S_START
    roffset = 0
    size = 0
    htab = Array(repeating: Int(0), count: HSIZE)
    codetab = Array(repeating: UInt16(0), count: HSIZE)

    /*
     * Layering compress on top of stdio in order to provide buffering,
     * and ensure that reads and write work with the data specified.
     */
    guard let fp = try? FileDescriptor.open(fname, mode) else {
      return nil
    }
    self.fp = fp
